mapper.select:
SELECT ap.* FROM AI_PROMPT ap INNER JOIN ( SELECT env_code, prompt_key, MAX(version) AS max_version FROM AI_PROMPT WHERE deleted = 0 GROUP BY env_code, prompt_key ) latest ON ap.env_code = latest.env_code AND ap.prompt_key = latest.prompt_key AND ap.version = latest.max_version WHERE ap.deleted = 0
AND ap.env_code = #{req.envCode}
AND ap.create_user = #{req.createUser}
AND ap.prompt_key = #{req.promptKey}
AND ap.prompt_title LIKE CONCAT('%', #{req.promptTitle}, '%')
AND ap.scene = #{req.scene}
AND ap.enabled_flag = #{req.enabledFlag}
ORDER BY ap.create_time DESC
